// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface OpdReasonIn {
  reason: string;
}

/** A ticket with its queue entry, invoice, pending approval and cash-back prompts (service.get_ticket). */
export interface OpdTicketDetailOut {
  ticket_id: number;
  ticket_number: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  dob: string | null;
  /** Null for a department-level ticket (no doctor chosen) */
  doctor_id: number | null;
  doctor_name: string | null;
  department_id: number | null;
  department_name: string | null;
  service_id: number | null;
  source: "WalkIn" | "Emergency" | "CodeRed" | "Referred" | "ReturnVisit";
  status: "Issued" | "Waiting" | "InConsultation" | "Examined" | "Completed" | "Deferred" | "Expired" | "Forfeited" | "Refunded" | "Void" | "Cancelled";
  payment_status: "Unpaid" | "PartiallyPaid" | "Paid" | "CreditAuthorized" | "Waivered" | "Refunded" | "PanelBilled";
  approval_lock: "None" | "RefundPending" | "WaiverPending" | "CreditPending";
  gross_amount: number;
  discount_amount: number;
  net_payable: number | null;
  discount_reason: string | null;
  issued_at: string;
  paid_at: string | null;
  /** The slip is valid for re-entry until then (set when settled) */
  valid_until: string | null;
  called_at: string | null;
  examined_at: string | null;
  completed_at: string | null;
  deferred_at: string | null;
  reactivated_at: string | null;
  expired_at: string | null;
  voided_at: string | null;
  void_reason: string | null;
  cancelled_at: string | null;
  /** Clinical notes are frozen (e.g. after an approved refund) */
  is_clinical_locked: boolean;
  clinical_lock_reason: string | null;
  is_emergency_bypass: boolean;
  is_ar_block_overridden: boolean;
  row_version: number;
  queue: OpdQueueEntryOut | null;
  invoice: InvoiceDetailOut | null;
  pending_approval: ApprovalSummaryOut | null;
  cash_back_prompts: CashBackPromptOut[];
}

/** The ticket's latest queue entry. */
export interface OpdQueueEntryOut {
  queue_id: number;
  /** doctor:<id> or department:<id> */
  queue_group: string;
  token_no: number;
  token_date: string;
  priority: number;
  status: "Active" | "Suspended" | "Deferred" | "Rerouted" | "Completed" | "Cancelled" | "Expired";
  queued_at: string;
  called_at: string | null;
  rerouted_from_queue_id: number | null;
}

/** An invoice with its lines and what is still due (billing.invoice_with_lines). */
export interface InvoiceDetailOut {
  invoice_id: number;
  invoice_no: string;
  invoice_type: "OPD" | "IPD" | "Pharmacy" | "Lab" | "Imaging" | "OT" | "OTC" | "Other";
  patient_id: number | null;
  admission_id: number | null;
  ticket_id: number | null;
  panel_id: number | null;
  employee_id: number | null;
  walkin_customer_name: string | null;
  walkin_customer_mobile: string | null;
  gross_total: number;
  discount_total: number;
  /** Null while the invoice is a draft */
  net_payable: number | null;
  amount_paid: number;
  amount_refunded: number;
  waiver_amount: number;
  waiver_dispensed_amount: number;
  credit_amount: number;
  status: "Draft" | "Open" | "PartiallyPaid" | "Paid" | "CreditAuthorized" | "Waivered" | "Refunded" | "Cancelled";
  /** Locked while an approval (waiver, credit, refund) is pending */
  is_locked: boolean;
  locked_reason: string | null;
  finalized_at: string | null;
  business_date: string;
  created_at: string;
  row_version: number;
  lines: InvoiceLineOut[];
  balance_due: number;
}

export interface InvoiceLineOut {
  invoice_item_id: number;
  line_type: "Consultation" | "Service" | "Drug" | "LabTest" | "Imaging" | "OTProcedure" | "OTConsumable" | "RoomCharge" | "Reversal";
  description: string;
  qty: number;
  unit_price: number;
  line_total: number;
  bed_day: string | null;
  /** Set on a reversal line: the line it cancels */
  reverses_item_id: number | null;
  reversal_reason: string | null;
  created_at: string;
}

/** The pending approval that currently locks a subject (e.g. an OPD ticket). */
export interface ApprovalSummaryOut {
  request_id: number;
  approval_type: "Refund" | "VIPWaiverPreConsult" | "VIPWaiverPostConsult" | "PatientCredit" | "PharmacyCharityOverride" | "LargeCashDrop" | "WardIndent" | "APPayment" | "PolicyChange" | "PrivilegedAccess";
  status: "Pending" | "Approved" | "Rejected" | "Cancelled";
  requested_at: string;
  summary: string;
}

/** Money reception must hand back when the slip is scanned (an approved refund or waiver). */
export interface CashBackPromptOut {
  kind: "Refund" | "WaiverRefund";
  /** The refund disbursement or waiver refund order to confirm */
  id: number;
  amount: number;
  message: string;
}

export interface RefundRequestIn {
  reason_code: "DoctorUnavailable" | "PatientRefusedTreatment" | "EmergencyDeparture" | "DuplicateTicket" | "BillingError" | "Other";
  note: string;
  /** Defaults to everything the patient paid */
  amount?: number | string | null;
}

export interface RefundRequestOut {
  refund_request_id: number;
  approval: ApprovalOut;
  ticket: OpdTicketDetailOut;
}

/** An approval request (service.APPROVAL_COLS). */
export interface ApprovalOut {
  request_id: number;
  approval_type: "Refund" | "VIPWaiverPreConsult" | "VIPWaiverPostConsult" | "PatientCredit" | "PharmacyCharityOverride" | "LargeCashDrop" | "WardIndent" | "APPayment" | "PolicyChange" | "PrivilegedAccess";
  /** Who may decide: every holder of this permission sees the request */
  required_permission: string;
  requester_id: number;
  requester_name: string;
  subject_type: string;
  subject_id: number;
  patient_id: number | null;
  amount: number | null;
  summary: string;
  /** Type-specific details the approver needs to decide */
  payload_jsonb: Record<string, unknown>;
  /** Needs the elevated approver (e.g. a large refund) */
  is_elevated: boolean;
  status: "Pending" | "Approved" | "Rejected" | "Cancelled";
  decided_by: number | null;
  decided_by_name: string | null;
  decided_at: string | null;
  decision_note: string | null;
  /** Decided by its own requester, the Owner of a solo practice (audit H-5); a risk item records it */
  solo_self_approved: boolean;
  requested_at: string;
  /** Whether you may approve or reject it now, by the rule the decision applies: show the buttons only when true (a type's own rule may still refuse, e.g. a large cash drop's decider is never the shift's cashier: DUAL_CONTROL_SAME_PERSON) */
  can_decide: boolean;
  /** Why you may not decide it, when can_decide is false; null when you may */
  decide_blocked: "decided" | "missing_permission" | "own_request" | null;
  /** On your own pending request: forbidden, or allowed_with_note for the Owner of a solo practice (solo_practice_mode on, nobody else holds the permission; a note is required and a risk item records it); null on anyone else's request or a decided one */
  self_decision: "forbidden" | "allowed_with_note" | null;
}

export interface WaiverRequestIn {
  reason: string;
  /** Pre-consult only; 100 = free ticket */
  waiver_pct?: number | string;
}

export interface WaiverRequestOut {
  waiver_request_id: number;
  approval: ApprovalOut;
  ticket: OpdTicketDetailOut;
}

export interface CreditRequestIn {
  /** Cash the patient can pay today */
  amount_paid_now?: number | string;
  method?: "Cash" | "Card" | "BankTransfer";
  reason: string;
  due_date?: string | null;
}

export interface CreditRequestOut {
  credit_request_id: number;
  approval: ApprovalOut;
  ticket: OpdTicketDetailOut;
}

/** Void an unpaid ticket (risk-monitored) — POST /api/v1/opd-tickets/{ticket_id}/void (who may call: holders of opd.ticket.void). */
export function voidOpdTickets(ticket_id: number, body: OpdReasonIn): Promise<OpdTicketDetailOut> {
  return api<OpdTicketDetailOut>("POST", `/opd-tickets/${ticket_id}/void`, body, { idempotent: true });
}

/** Initiate Refund (needs approval) — POST /api/v1/opd-tickets/{ticket_id}/refund-request (who may call: holders of opd.refund.request). */
export function refundRequest(ticket_id: number, body: RefundRequestIn): Promise<RefundRequestOut> {
  return api<RefundRequestOut>("POST", `/opd-tickets/${ticket_id}/refund-request`, body, { idempotent: true });
}

/** Request VIP / 100% waiver BEFORE consultation (needs approval) — POST /api/v1/opd-tickets/{ticket_id}/vip-waiver-request (who may call: holders of opd.waiver.request). */
export function preconsultWaiver(ticket_id: number, body: WaiverRequestIn): Promise<WaiverRequestOut> {
  return api<WaiverRequestOut>("POST", `/opd-tickets/${ticket_id}/vip-waiver-request`, body, { idempotent: true });
}

/** Request Credit / Partial Payment — POST /api/v1/opd-tickets/{ticket_id}/credit-request (who may call: holders of opd.credit.request). */
export function creditRequest(ticket_id: number, body: CreditRequestIn): Promise<CreditRequestOut> {
  return api<CreditRequestOut>("POST", `/opd-tickets/${ticket_id}/credit-request`, body, { idempotent: true });
}

/** Ticket with invoice, queue entry, pending approval and cash-back prompts — GET /api/v1/opd-tickets/{ticket_id} (who may call: holders of opd.ticket.view or opd.queue.doctor). */
export function getTicket(ticket_id: number): Promise<OpdTicketDetailOut> {
  return api<OpdTicketDetailOut>("GET", `/opd-tickets/${ticket_id}`, undefined);
}

/** Approval queue visible to me (or my own requests with mine=true) — GET /api/v1/approvals (who may call: any logged-in user: the pending requests whose required_permission they hold, or their own with mine=true). */
export function listApprovals(query?: { status?: "Pending" | "Approved" | "Rejected" | "Cancelled"; mine?: boolean; limit?: number }): Promise<ApprovalOut[]> {
  return api<ApprovalOut[]>("GET", withQuery(`/approvals`, query), undefined);
}
